import numpy as np, torch, model
net=model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c2_blocks.1_k10.npy')); b=-28.2556
R=[5,9,10,15]
def run(xi,c,delta,lo,hi):
    x=torch.as_tensor(xi,dtype=torch.float32); cc=torch.as_tensor(c,dtype=torch.float32)
    fired=torch.zeros(len(x),dtype=torch.bool); d=torch.tensor(delta,dtype=torch.float32)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,cc,('blocks.1',),count=False)
        if lo<=k<hi:
            f=(a['blocks.1']@w+b>0); v=v+f.float()[:,None]*d; fired|=f
        x=x-v/20
    return x.numpy(),fired.numpy()
torch.manual_seed(1)
N=256
XI={i:torch.randn(N,2) for i in R}
base={i:run(XI[i],np.full(N,neg['c'][i]),(0,0),0,0)[0] for i in R}
# reference cloud for typicality at each c
for i in R: print(i,'base res',model.in_basin(i,torch.tensor(base[i])).float().mean().item() if torch.is_tensor(model.in_basin(i,torch.tensor(base[i]))) else np.mean(model.in_basin(i,base[i])))
def score(delta,lo,hi):
    res=[];off=[];mov=[]
    for i in R:
        a,f=run(XI[i],np.full(N,neg['c'][i]),delta,lo,hi)
        ib=np.asarray(model.in_basin(i,a)); res.append(ib.mean())
        # off-distribution: nn distance to base cloud
        d=np.sqrt(((a[:,None]-base[i][None])**2).sum(-1)); nn=np.sort(d,1)[:,1] if False else d.min(1)
        off.append((nn>0.3).mean()); mov.append(f.mean())
    return np.mean(res),np.mean(off),np.mean(mov)
out=[]
for lo,hi in [(4,12),(6,12),(8,12),(2,12),(0,12)]:
  for ang in range(0,360,45):
    for mag in [2,4,8]:
      d=(mag*np.cos(np.radians(ang)),mag*np.sin(np.radians(ang)))
      r,o,m=score(d,lo,hi); out.append((r,o,m,lo,hi,ang,mag))
out.sort()
for z in out[:20]: print(np.round(z,3))

