w=torch.tensor(np.load('c5_detw.npy')); b=-10.6641
e=torch.tensor([1.,-1.])/2**0.5; up=torch.tensor([0.,1.])
S={}
def hact(m,i,o): S['fire']=(o@w+b>S['thr'])
def hout(m,i,o):
    cfg=S['cfg']
